        /// <param name="tcrGrupoArchivo">Grupo de archivos "01" = grupo de archivos 01 ... 02,03..</param>
        /// <returns></returns>
        public static bool flgEliminarRegistro(String tcrCodigoEvento, String tcrGrupoArchivo)
        {
            var llgReturn = false;
            ModeloHclregisextxa.fcvEliminarEvento(tcrCodigoEvento, tcrGrupoArchivo);
            ModeloHclregisextxb.fcvEliminarEvento(tcrCodigoEvento, tcrGrupoArchivo);
            ModeloHclregisexnum.fcvEliminarEvento(tcrCodigoEvento, tcrGrupoArchivo);
            ModeloHclregisexcbo.fcvEliminarEvento(tcrCodigoEvento, tcrGrupoArchivo);
            ModeloHclregisexcbx.fcvEliminarEvento(tcrCodigoEvento, tcrGrupoArchivo);
            ModeloHclregisexrec.fcvEliminarEvento(tcrCodigoEvento, tcrGrupoArchivo);
            ModeloHclregisexfec.fcvEliminarEvento(tcrCodigoEvento, tcrGrupoArchivo);
            ModeloHclregisexrel.fcvEliminarEvento(tcrCodigoEvento, tcrGrupoArchivo);
            ModeloHclregisexrbt.fcvEliminarEvento(tcrCodigoEvento, tcrGrupoArchivo);
            ModeloHclregisexmem.fcvEliminarEvento(tcrCodigoEvento, tcrGrupoArchivo);
            ModeloHclregisexmen.fcvEliminarEvento(tcrCodigoEvento, tcrGrupoArchivo);
            ModeloHclregisexmeo.fcvEliminarEvento(tcrCodigoEvento, tcrGrupoArchivo);
            ModeloHclregisexchk.fcvEliminarEvento(tcrCodigoEvento, tcrGrupoArchivo);
            ModeloHclregisexchl.fcvEliminarEvento(tcrCodigoEvento, tcrGrupoArchivo);
            return llgReturn;
        }
        #endregion
        // Consulta nativa SQL archivos historicos para resolucion 4505
        #region flsSQLDataTableHistoricos4505: Consulta nativa SQL archivos historicos para 4505
        /// <summary>
        /// Consulta nativa SQL para lista registros desde archivos historicos para resolucion 4505
        /// </summary>
        /// <param name="tdaFechaInicial">Fecha inicial del periodo a consultar en historicos</param>
        /// <param name="tdaFechaFinal">Fecha final del periodo a consultar en historicos</param>
        /// <param name="tcrArchivo">Nombre del archivo historico a consultar pude ser: "hclregisextxb01" / "hclregisextxa01"...</param>
        /// <returns>Devuelve un temporal del tipo DataTable</returns>
        public static DataTable flsSQLDataTableHistoricos4505(String tcrCodigoEps, DateTime tdaFechaInicial, DateTime tdaFechaFinal, String tcrArchivo)
        {
            var lcrFechaIni = tdaFechaInicial.ToShortDateString();
            var lcrFechaFin = tdaFechaFinal.ToShortDateString();

            var tmpArchivo = flsSQLDataTableHistoricos4505(tcrCodigoEps, lcrFechaIni, lcrFechaFin, tcrArchivo);

            return tmpArchivo;
        }
        #endregion
        #region flsSQLDataTableHistoricos4505: Consulta nativa SQL archivos historicos para 4505
        /// <summary>
        /// Consulta nativa SQL para lista registros desde archivos historicos para resolucion 4505
        /// </summary>
        /// <param name="tcrFechaInicial">Fecha inicial (en formato texto) del periodo a consultar en historicos</param>
        /// <param name="tcrFechaFinal">Fecha final (en formato texto) del periodo a consultar en historicos</param>
        /// <param name="tcrArchivo">Nombre del archivo historico a consultar pude ser: "hclregisextxb01" / "hclregisextxa01"...</param>
        /// <returns>Devuelve un temporal del tipo DataTable</returns>
        public static DataTable flsSQLDataTableHistoricos4505(String tcrCodigoEps, String tcrFechaInicial, String tcrFechaFinal, String tcrArchivo)
        {
            var lcrFechaIni = Funciones.fcrFechaTextoCambiarFormato("DMY", "/", tcrFechaInicial, "YMD", "-");
            var lcrFechaFin = Funciones.fcrFechaTextoCambiarFormato("DMY", "/", tcrFechaFinal, "YMD", "-");
            var lcrLineaSqlSelct = String.Empty;

            if (String.IsNullOrWhiteSpace(tcrCodigoEps))
            {
                // Realizar consulta nativa SQL 
                lcrLineaSqlSelct = "SELECT " + tcrArchivo + ".*, admregadmision.sia_nroide_usua,admregadmision.adm_pacemb_rgad,admregadmision.adm_fecadm_rgad," +
                                       "       admregadmision.sia_regate_rgat,admregadmision.sia_codeps_teps,admregadmision.adm_nroreg_tria," +
                                       "       admregadmision.sia_edaano_usua,admregadmision.sia_edames_usua,admregadmision.sia_edadia_usua" +
                                       "       FROM " + tcrArchivo +
                                       " INNER JOIN spactivmedicgen ON (" + tcrArchivo + ".hcl_codreg_hcca = spactivmedicgen.hcl_codreg_hcca)" +
                                       " INNER JOIN admregadmision ON (" + tcrArchivo + ".adm_secadm_rgad = admregadmision.adm_secadm_rgad)" +
                                       "      WHERE hcl_gesfec_hcev >= '" + lcrFechaIni + "' AND" +
                                       "            hcl_gesfec_hcev <= '" + lcrFechaFin + "' AND" +
                                       "            spactivmedicgen.ssp_estreg_ssam = '1'" +
                                       "   ORDER BY " + tcrArchivo + ".grp_idepla_grpv," + tcrArchivo + ".hcl_gesfec_hcev";

            }
            else
            {
                // Realizar consulta nativa SQL 
                lcrLineaSqlSelct = "SELECT " + tcrArchivo + ".*, admregadmision.sia_nroide_usua,admregadmision.adm_pacemb_rgad,admregadmision.adm_fecadm_rgad," +
                                       "       admregadmision.sia_regate_rgat,admregadmision.sia_codeps_teps,admregadmision.adm_nroreg_tria," +
                                       "       admregadmision.sia_edaano_usua,admregadmision.sia_edames_usua,admregadmision.sia_edadia_usua" +
                                       "       FROM " + tcrArchivo +
                                       " INNER JOIN spactivmedicgen ON (" + tcrArchivo + ".hcl_codreg_hcca = spactivmedicgen.hcl_codreg_hcca)" +
                                       " INNER JOIN admregadmision ON (" + tcrArchivo + ".adm_secadm_rgad = admregadmision.adm_secadm_rgad)" +
                                       "      WHERE hcl_gesfec_hcev >= '" + lcrFechaIni + "' AND" +
                                       "            hcl_gesfec_hcev <= '" + lcrFechaFin + "' AND" +
                                       "            admregadmision.sia_codeps_teps = '" + tcrCodigoEps + "' AND" +
                                       "            spactivmedicgen.ssp_estreg_ssam = '1'" +
                                       "   ORDER BY " + tcrArchivo + ".grp_idepla_grpv," + tcrArchivo + ".hcl_gesfec_hcev";
            }

            var tmpArchivo = Funciones.fobConsultaSqlDataAdapter(lcrLineaSqlSelct);

            return tmpArchivo;
        }
        #endregion
        #region flsSQLDataTableDatosAdmision: Consulta nativa SQL para archivo de admision
        /// <summary>
        /// Consulta nativa SQL para lista registros pacientes embarazadas desde archivo de admision
        /// </summary>
        /// <param name="tcrFechaInicial">Fecha inicial (en formato texto) del periodo a consultar en historicos</param>
        /// <param name="tcrFechaFinal">Fecha final (en formato texto) del periodo a consultar en historicos</param>
        /// <returns>Devuelve un temporal del tipo DataTable</returns>
        public static DataTable flsSQLDataTableDatosAdmision(String tcrCodigoEps, String tcrFechaInicial, String tcrFechaFinal)
        {
            var lcrFechaIni      = Funciones.fcrFechaTextoCambiarFormato("DMY", "/", tcrFechaInicial, "YMD", "-");
            var lcrFechaFin      = Funciones.fcrFechaTextoCambiarFormato("DMY", "/", tcrFechaFinal, "YMD", "-");
            var lcrLineaSqlSelct = String.Empty;

            // Realizar consulta nativa SQL 
            if (String.IsNullOrWhiteSpace(tcrCodigoEps))
            {
                lcrLineaSqlSelct = "SELECT admregadmision.* " +
                                   "       FROM admregadmision " +
                                   "      WHERE admregadmision.adm_fecadm_rgad >= '" + lcrFechaIni + "' AND" +
                                   "            admregadmision.adm_fecadm_rgad <= '" + lcrFechaFin + "' AND" +
                                   "            admregadmision.adm_pacemb_rgad = '1' AND" +
                                   "            admregadmision.sis_estpro_espr = '2'" +
                                   "   ORDER BY admregadmision.adm_fecadm_rgad";
            }
            else 
            {
                lcrLineaSqlSelct = "SELECT admregadmision.* " +
                                   "       FROM admregadmision " +
                                   "      WHERE admregadmision.adm_fecadm_rgad >= '" + lcrFechaIni + "' AND" +
                                   "            admregadmision.adm_fecadm_rgad <= '" + lcrFechaFin + "' AND" +
                                   "            admregadmision.adm_pacemb_rgad = '1' AND" +
                                   "            admregadmision.sia_codeps_teps = '" + tcrCodigoEps + "' AND" +
                                   "            admregadmision.sis_estpro_espr = '2'" +
                                   "   ORDER BY admregadmision.adm_fecadm_rgad";

            }

            var tmpArchivo = Funciones.fobConsultaSqlDataAdapter(lcrLineaSqlSelct);

            return tmpArchivo;
        }
        #endregion
        #region flsSQLDataTableHistoricos4505ID: Consulta nativa SQL archivos historicos para 4505 solo un usuario
        /// <summary>
        /// Consulta nativa SQL para lista registros desde archivos historicos para resolucion 4505  solo un usuario
        /// </summary>
        /// <param name="tcrIDUnicoUsuario">Numero id unica del usuario en la base de datos</param>
