        public static DataTable flsSQLDataTableHistoricos4505ID(String tcrIDUnicoUsuario, String tcrLlaveActividad, 
                                                                DateTime tdaFechaInicial, DateTime tdaFechaFinal, String tcrArchivo)
        {
            var lcrFechaIni = tdaFechaInicial.ToShortDateString();
            var lcrFechaFin = tdaFechaFinal.ToShortDateString();

            var tmpArchivo = flsSQLDataTableHistoricos4505ID(tcrIDUnicoUsuario, tcrLlaveActividad, lcrFechaIni, lcrFechaFin, tcrArchivo);

            return tmpArchivo;
        }
        #endregion
        #region flsSQLDataTableHistoricos4505ID: Consulta nativa SQL archivos historicos para 4505  solo un usuario
        /// <summary>
        /// Consulta nativa SQL para lista registros desde archivos historicos para resolucion 4505  solo un usuario
        /// </summary>
        /// <param name="tcrIDUnicoUsuario">Numero id unica del usuario en la base de datos</param>
        /// <param name="tcrLlaveActividad">Llave de la actividad medica en Historia clinica ejemplo: "RESULT-LAB-CITOLOGIA"</param>
        /// <param name="tcrFechaInicial">Fecha inicial (en formato texto) del periodo a consultar en historicos</param>
        /// <param name="tcrFechaFinal">Fecha final (en formato texto) del periodo a consultar en historicos</param>
        /// <param name="tcrArchivo">Nombre del archivo historico a consultar pude ser: "hclregisextxb01" / "hclregisextxa01"...</param>
        /// <returns>Devuelve un temporal del tipo DataTable</returns>
        public static DataTable flsSQLDataTableHistoricos4505ID(String tcrIDUnicoUsuario, String tcrLlaveActividad, 
                                                                String tcrFechaInicial, String tcrFechaFinal, String tcrArchivo)
        {
            var lcrFechaIni = Funciones.fcrFechaTextoCambiarFormato("DMY", "/", tcrFechaInicial, "YMD", "-");
            var lcrFechaFin = Funciones.fcrFechaTextoCambiarFormato("DMY", "/", tcrFechaFinal, "YMD", "-");
            var lcrLineaSqlSelct = String.Empty;

                // Realizar consulta nativa SQL 
            lcrLineaSqlSelct = "SELECT " + tcrArchivo + ".*, admregadmision.sia_nroide_usua,admregadmision.adm_pacemb_rgad,admregadmision.adm_fecadm_rgad," +
                                   "       admregadmision.sia_regate_rgat,admregadmision.sia_codeps_teps,admregadmision.adm_nroreg_tria," +
                                   "       admregadmision.sia_edaano_usua,admregadmision.sia_edames_usua,admregadmision.sia_edadia_usua" +
                                   "       FROM " + tcrArchivo +
                                   " INNER JOIN admregadmision ON (" + tcrArchivo + ".adm_secadm_rgad = admregadmision.adm_secadm_rgad)" +
                                   "      WHERE hcl_gesfec_hcev >= '" + lcrFechaIni + "' AND" +
                                   "            hcl_gesfec_hcev <= '" + lcrFechaFin + "' AND" +
                                   "            admregadmision.sia_idesec_usua = '" + tcrIDUnicoUsuario + "' AND" +
                                   "            " + tcrArchivo + ".hcl_codreg_hcca = '" + tcrLlaveActividad + "'  LIMIT 1;";

            var tmpArchivo = Funciones.fobConsultaSqlDataAdapter(lcrLineaSqlSelct);

            return tmpArchivo;
        }
        #endregion

    }
