        #region Metodos para edicion de registros
        #region  fcvActualizar: Agregar o Modificar Registro
        /// <summary>
        /// Genera un nuevo registro dentro del historico 01 02 03..., dado el parametro tcrGrupoArchivo
        /// </summary>
        /// <param name="tobjModelo">Registro de datos a guardar </param>
        /// <param name="tcrGrupoArchivo">Grupo de archivos pude ser: "01" / "02" / "03" / "04"...</param>
        /// <returns></returns>
        public static void fcvActualizar(ModeloHclregisextxb tobjModelo, String tcrGrupoArchivo)
        {
            try
            {
                using (_context = new DbAplicacion())
                {
                    // Archivo del Grupo 01
                    if (tcrGrupoArchivo == "01")
                    {
                        #region Archivo 01 Gestion registro
                        var lobjReg01 = _context.Hclregisextxb01.FirstOrDefault(p => p.hcl_nroreg_hcta == tobjModelo.Hcl_nroreg_hcta);
                        if (lobjReg01 != null)
                        {
                            // Se modifica
                            fobCargarRegistroArchivo01(ref lobjReg01, tobjModelo);
                        }
                        else
                        {
                            // Se agrega
                            lobjReg01 = new EFhclregisextxb01();
                            fobCargarRegistroArchivo01(ref lobjReg01, tobjModelo);
                            //lobjReg01.hcl_nroreg_hcta = tobjModelo.Hcl_nroreg_hcev;
                            _context.AddToHclregisextxb01(lobjReg01);
                            _context.SaveChanges();
                        }
                        _context.SaveChanges();
                        #endregion
                    }
                    else if (tcrGrupoArchivo == "02")
                    {
                        // Nuevos grupos
                    }
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message, "Modelo Error Metodo: fcvActualizar");
            }
        }
        #endregion
        #region Eliminar registro
        public static void fcvEliminar(String tcrCodigo, String tcrGrupoArchivo)
        {
            try
            {
                using (_context = new DbAplicacion())
                {
                    // Archivo del Grupo 01
                    if (tcrGrupoArchivo == "01")
                    {
                        #region Archivo 01 Gestion registro
                        var lobjRegistro = _context.Hclregisextxb01.FirstOrDefault(p => p.hcl_nroreg_hcta == tcrCodigo);
                        if (lobjRegistro != null)
                        {
                            _context.DeleteObject(lobjRegistro);
                            _context.SaveChanges();
                        }
                        #endregion
                    }
                    else if (tcrGrupoArchivo == "02")
                    {
                        // Nuevos grupos
                    }
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message, "Modelo Error Metodo: fcvEliminar");
            }
        }
        #endregion
        #region Eliminar registro Evento
        public static void fcvEliminarEvento(String tcrCodigo, String tcrGrupoArchivo)
        {
            try
            {
                using (_context = new DbAplicacion())
                {
                    // Archivo del Grupo 01
                    if (tcrGrupoArchivo == "01")
                    {
                        #region Archivo 01 Gestion registro
                        var lobjRegistro = _context.Hclregisextxb01.FirstOrDefault(p => p.hcl_nroreg_hcev == tcrCodigo);
                        if (lobjRegistro != null)
                        {
                            _context.DeleteObject(lobjRegistro);
                            _context.SaveChanges();
                        }
                        #endregion
                    }
                    else if (tcrGrupoArchivo == "02")
