        /// <param name="tcrGrupoArchivo">Grupo de archivos pude ser: "01" / "02" / "03" / "04"...</param>
        /// <returns></returns>
        public static void fcvActualizar(ModeloHclregisextxc tobjModelo, String tcrGrupoArchivo)
        {
            try
            {
                using (_context = new DbAplicacion())
                {
                    // Archivo del Grupo 01
                    if (tcrGrupoArchivo == "01")
                    {
                        #region Archivo 01 Gestion registro
                        var lobjReg01 = _context.Hclregisextxc01.FirstOrDefault(p => p.hcl_nroreg_hctc == tobjModelo.Hcl_nroreg_hctc);
                        if (lobjReg01 != null)
                        {
                            // Se modifica
                            fobCargarRegistroArchivo01(ref lobjReg01, tobjModelo);
                        }
                        else
                        {
                            // Se agrega
                            lobjReg01 = new EFhclregisextxc01();
                            fobCargarRegistroArchivo01(ref lobjReg01, tobjModelo);
                            //lobjReg01.hcl_nroreg_hcta = tobjModelo.Hcl_nroreg_hcev;
                            _context.AddToHclregisextxc01(lobjReg01);
                            _context.SaveChanges();
                        }
                        _context.SaveChanges();
                        #endregion
                    }
                    else if (tcrGrupoArchivo == "02")
                    {
                        // Nuevos grupos
                    }
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message, "Modelo Error Metodo: fcvActualizar");
            }
        }
        #endregion
