        // Filtro segun grupo archivo
        #region Registro
        /// <summary>
        ///  Devolver un registro
        /// </summary>
        /// <param name="tcrTipoLlave">Tipo llave busqueda "IG" = Codigo unico del registro "R1" = Codigo unico del evento medico</param>
        /// <param name="tcrBuscar">Valor de la llave o numero del registro a buscar </param>
        /// <param name="tcrGrupoArchivo">Grupo Archivo "01","02,"03",...</param>
        /// <returns></returns>
        public static ModeloHclregisextxc fobRegistroArchivo(String tcrTipoLlave, String tcrBuscar, String tcrGrupoArchivo)
        {
            ModeloHclregisextxc lobRegConsulta = null;
            var lobTemp = flsListaRegistrosArchivo(tcrTipoLlave, tcrBuscar, tcrGrupoArchivo);

            if (lobTemp != null && lobTemp.Count != 0)
            {
                lobRegConsulta = lobTemp.FirstOrDefault();
            }

            return lobRegConsulta;
        }
        #endregion
        #region Listar Registros
        /// <summary>
        ///  Devolver lista de registros 
        /// </summary>
        /// <param name="tcrTipoLlave">Tipo llave busqueda "IG" = Codigo unico del registro "R1" = Codigo unico del evento medico</param>
        /// <param name="tcrBuscar">Valor de la llave o numero del registro a buscar </param>
        /// <param name="tcrGrupoArchivo">Grupo Archivo "01","02,"03",...</param>
        /// <returns></returns>
        public static List<ModeloHclregisextxc> flsListaRegistrosArchivo(String tcrTipoLlave, String tcrBuscar, String tcrGrupoArchivo)
        {
            List<ModeloHclregisextxc> lobConsulta = null;
            if (tcrGrupoArchivo == "01")
            {
                lobConsulta = flsListaRegistrosArchivo01(tcrTipoLlave, tcrBuscar);
            }
            else if (tcrGrupoArchivo == "02")
            {
                // Nuevo grupo de archivos
            }
            return lobConsulta;
        }
        #endregion
        #region flsListaRegistrosArchivo01: Filtro Archivo 01
        /// <summary>
        ///  Devlver lista de registros 
        /// </summary>
        /// <param name="tcrTipoLlave">Tipo llave busqueda "IG" = Codigo unico del registro "R1" = Codigo unico del evento medico</param>
        /// <param name="tcrBuscar">Valor de la llave o numero del registro a buscar </param>
        /// <returns></returns>
        public static List<ModeloHclregisextxc> flsListaRegistrosArchivo01(String tcrTipoLlave, String tcrBuscar)
        {
            List<ModeloHclregisextxc> lobConsulta = null;
            IQueryable<ModeloHclregisextxc> lobTmp = null;

            using (_context = new DbAplicacion())
            {
                if (tcrTipoLlave == "IG")
                {
                    lobTmp = from hclregisextxc in _context.Hclregisextxc01
                                      where hclregisextxc.hcl_nroreg_hctc == tcrBuscar
                                      select new ModeloHclregisextxc
                                      {
                                          #region Datos
                                          Hcl_nroreg_hctc = hclregisextxc.hcl_nroreg_hctc,
                                          Grp_idereg_grpl = hclregisextxc.grp_idereg_grpl,
                                          Hcl_nroreg_hcev = hclregisextxc.hcl_nroreg_hcev,
                                          Hcl_codreg_hcca = hclregisextxc.hcl_codreg_hcca,
                                          Adm_secadm_rgad = hclregisextxc.adm_secadm_rgad,
                                          Cit_codasi_mcit = hclregisextxc.cit_codasi_mcit,
                                          Fcm_codcpr_cpro = hclregisextxc.fcm_codcpr_cpro,
                                          Sia_idesec_usua = hclregisextxc.sia_idesec_usua,
                                          Hcl_gesfec_hcev = (DateTime)hclregisextxc.hcl_gesfec_hcev,
