                        #region Archivo 01 Gestion registro
                        var lobjRegistro = _context.Hclregisexcbo01.FirstOrDefault(p => p.hcl_nroreg_hccb == tcrCodigo);
                        if (lobjRegistro != null)
                        {
                            _context.DeleteObject(lobjRegistro);
                            _context.SaveChanges();
                        }
                        #endregion
                    }
                    else if (tcrGrupoArchivo == "02")
