        // Filtro segun grupo archivo
        #region Registro
        /// <summary>
        ///  Devolver un registro
        /// </summary>
        /// <param name="tcrTipoLlave">Tipo llave busqueda "IG" = Codigo unico del registro "R1" = Codigo unico del evento medico</param>
        /// <param name="tcrBuscar">Valor de la llave o numero del registro a buscar </param>
        /// <param name="tcrGrupoArchivo">Grupo Archivo "01","02,"03",...</param>
        /// <returns></returns>
        public static ModeloHclregisexcbo fobRegistroArchivo(String tcrTipoLlave, String tcrBuscar, String tcrGrupoArchivo)
        {
            ModeloHclregisexcbo lobRegConsulta = null;
            var lobTemp = flsListaRegistrosArchivo(tcrTipoLlave, tcrBuscar, tcrGrupoArchivo);

            if (lobTemp != null && lobTemp.Count != 0)
            {
                lobRegConsulta = lobTemp.FirstOrDefault();
            }

            return lobRegConsulta;
        }
        #endregion
        #region Listar Registros
        /// <summary>
        ///  Devolver lista de registros 
        /// </summary>
        /// <param name="tcrTipoLlave">Tipo llave busqueda "IG" = Codigo unico del registro "R1" = Codigo unico del evento medico</param>
        /// <param name="tcrBuscar">Valor de la llave o numero del registro a buscar </param>
        /// <param name="tcrGrupoArchivo">Grupo Archivo "01","02,"03",...</param>
        /// <returns></returns>
        public static List<ModeloHclregisexcbo> flsListaRegistrosArchivo(String tcrTipoLlave, String tcrBuscar, String tcrGrupoArchivo)
        {
            List<ModeloHclregisexcbo> lobConsulta = null;
            if (tcrGrupoArchivo == "01")
            {
                lobConsulta = flsListaRegistrosArchivo01(tcrTipoLlave, tcrBuscar);
            }
            else if (tcrGrupoArchivo == "02")
            {
                // Nuevo grupo de archivos
            }
            return lobConsulta;
        }
        #endregion
        #region flsListaRegistrosArchivo01: Filtro Archivo 01
        /// <summary>
        ///  Devlver lista de registros 
        /// </summary>
        /// <param name="tcrTipoLlave">Tipo llave busqueda "IG" = Codigo unico del registro "R1" = Codigo unico del evento medico</param>
        /// <param name="tcrBuscar">Valor de la llave o numero del registro a buscar </param>
        /// <returns></returns>
        public static List<ModeloHclregisexcbo> flsListaRegistrosArchivo01(String tcrTipoLlave, String tcrBuscar)
        {
            List<ModeloHclregisexcbo> lobConsulta = null;
            IQueryable<ModeloHclregisexcbo> lobTmp = null;
            using (_context = new DbAplicacion())
            {
                if (tcrTipoLlave == "IG")
                {

                    lobTmp = from hclregisexcbo in _context.Hclregisexcbo01
                             where hclregisexcbo.hcl_nroreg_hccb == tcrBuscar
                             select new ModeloHclregisexcbo
                             {
