        public static List<ModeloHclregisexcbx> flsListaRegistrosArchivo(String tcrTipoLlave, String tcrBuscar, String tcrGrupoArchivo)
        {
            List<ModeloHclregisexcbx> lobConsulta = null;
            if (tcrGrupoArchivo == "01")
            {
                lobConsulta = flsListaRegistrosArchivo01(tcrTipoLlave, tcrBuscar);
            }
            else if (tcrGrupoArchivo == "02")
            {
                // Nuevo grupo de archivos
            }
            return lobConsulta;
        }
