        // Filtro segun grupo archivo
        #region Registro
        /// <summary>
        ///  Devolver un registro
        /// </summary>
        /// <param name="tcrTipoLlave">Tipo llave busqueda "IG" = Codigo unico del registro "R1" = Codigo unico del evento medico</param>
        /// <param name="tcrBuscar">Valor de la llave o numero del registro a buscar </param>
        /// <param name="tcrGrupoArchivo">Grupo Archivo "01","02,"03",...</param>
        /// <returns></returns>
        public static ModeloHclregisexrbm fobRegistroArchivo(String tcrTipoLlave, String tcrBuscar, String tcrGrupoArchivo)
        {
            ModeloHclregisexrbm lobRegConsulta = null;
            var lobTemp = flsListaRegistrosArchivo(tcrTipoLlave, tcrBuscar, tcrGrupoArchivo);

            if (lobTemp != null && lobTemp.Count != 0)
            {
                lobRegConsulta = lobTemp.FirstOrDefault();
            }

            return lobRegConsulta;
        }
        #endregion
        #region Listar Registros
        /// <summary>
        ///  Devolver lista de registros 
        /// </summary>
        /// <param name="tcrTipoLlave">Tipo llave busqueda "IG" = Codigo unico del registro "R1" = Codigo unico del evento medico</param>
        /// <param name="tcrBuscar">Valor de la llave o numero del registro a buscar </param>
        /// <param name="tcrGrupoArchivo">Grupo Archivo "01","02,"03",...</param>
        /// <returns></returns>
        public static List<ModeloHclregisexrbm> flsListaRegistrosArchivo(String tcrTipoLlave, String tcrBuscar, String tcrGrupoArchivo)
        {
            List<ModeloHclregisexrbm> lobConsulta = null;
            if (tcrGrupoArchivo == "01")
            {
                lobConsulta = flsListaRegistrosArchivo01(tcrTipoLlave, tcrBuscar);
            }
            else if (tcrGrupoArchivo == "02")
            {
                // Nuevo grupo de archivos
            }
            return lobConsulta;
        }
        #endregion
        #region flsListaRegistrosArchivo01: Filtro Archivo 01
        /// <summary>
        ///  Devlver lista de registros 
        /// </summary>
        /// <param name="tcrTipoLlave">Tipo llave busqueda "IG" = Codigo unico del registro "R1" = Codigo unico del evento medico</param>
        /// <param name="tcrBuscar">Valor de la llave o numero del registro a buscar </param>
        /// <returns></returns>
        public static List<ModeloHclregisexrbm> flsListaRegistrosArchivo01(String tcrTipoLlave, String tcrBuscar)
        {
            List<ModeloHclregisexrbm> lobConsulta = null;
            IQueryable<ModeloHclregisexrbm> lobTmp = null;

            using (_context = new DbAplicacion())
            {
                if (tcrTipoLlave == "IG")
                {
                    lobTmp = from hclregisexrbm in _context.Hclregisexrbm01
                             where hclregisexrbm.hcl_nroreg_hcbm == tcrBuscar
                             select new ModeloHclregisexrbm
                             {
                                 #region Datos
                                 Hcl_nroreg_hcbm = hclregisexrbm.hcl_nroreg_hcbm,
                                 Grp_idereg_grpl = hclregisexrbm.grp_idereg_grpl,
                                 Hcl_nroreg_hcev = hclregisexrbm.hcl_nroreg_hcev,
                                 Hcl_codreg_hcca = hclregisexrbm.hcl_codreg_hcca,
                                 Adm_secadm_rgad = hclregisexrbm.adm_secadm_rgad,
                                 Cit_codasi_mcit = hclregisexrbm.cit_codasi_mcit,
                                 Fcm_codcpr_cpro = hclregisexrbm.fcm_codcpr_cpro,
                                 Sia_idesec_usua = hclregisexrbm.sia_idesec_usua,
                                 Hcl_gesfec_hcev = (DateTime)hclregisexrbm.hcl_gesfec_hcev,
                                 Hcl_geshor_hcev = (Decimal)hclregisexrbm.hcl_geshor_hcev,
