        /// <summary>
        ///  Devolver un registro
        /// </summary>
        /// <param name="tcrTipoLlave">Tipo llave busqueda "IG" = Codigo unico del registro "R1" = Codigo unico del evento medico</param>
        /// <param name="tcrBuscar">Valor de la llave o numero del registro a buscar </param>
