        public static void fcvEliminar(String tcrCodigo, String tcrGrupoArchivo)
        {
            try
            {
                using (_context = new DbAplicacion())
                {
                    // Archivo del Grupo 01
                    if (tcrGrupoArchivo == "01")
                    {
                        #region Archivo 01 Gestion registro
                        var lobjRegistro = _context.Hclregisexmen01.FirstOrDefault(p => p.hcl_nroreg_hcmn == tcrCodigo);
                        if (lobjRegistro != null)
                        {
                            _context.DeleteObject(lobjRegistro);
                            _context.SaveChanges();
                        }
                        #endregion
                    }
                    else if (tcrGrupoArchivo == "02")
                    {
                        // Nuevos grupos
                    }
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message, "Modelo Error Metodo: fcvEliminar");
            }
        }
