        #endregion
        // Filtro segun grupo archivo
        #region Registro
        /// <summary>
        ///  Devolver un registro
        /// </summary>
        /// <param name="tcrTipoLlave">Tipo llave busqueda "IG" = Codigo unico del registro "R1" = Codigo unico del evento medico</param>
        /// <param name="tcrBuscar">Valor de la llave o numero del registro a buscar </param>
        /// <param name="tcrGrupoArchivo">Grupo Archivo "01","02,"03",...</param>
        /// <returns></returns>
        public static ModeloHclregisexchl fobRegistroArchivo(String tcrTipoLlave, String tcrBuscar, String tcrGrupoArchivo)
        {
            ModeloHclregisexchl lobRegConsulta = null;
            var lobTemp = flsListaRegistrosArchivo(tcrTipoLlave, tcrBuscar, tcrGrupoArchivo);

            if (lobTemp != null && lobTemp.Count != 0)
            {
                lobRegConsulta = lobTemp.FirstOrDefault();
            }

            return lobRegConsulta;
        }
        #endregion
        #region Listar Registros
        /// <summary>
        ///  Devolver lista de registros 
        /// </summary>
        /// <param name="tcrTipoLlave">Tipo llave busqueda "IG" = Codigo unico del registro "R1" = Codigo unico del evento medico</param>
        /// <param name="tcrBuscar">Valor de la llave o numero del registro a buscar </param>
        /// <param name="tcrGrupoArchivo">Grupo Archivo "01","02,"03",...</param>
        /// <returns></returns>
        public static List<ModeloHclregisexchl> flsListaRegistrosArchivo(String tcrTipoLlave, String tcrBuscar, String tcrGrupoArchivo)
        {
            List<ModeloHclregisexchl> lobConsulta = null;
            if (tcrGrupoArchivo == "01")
            {
                lobConsulta = flsListaRegistrosArchivo01(tcrTipoLlave, tcrBuscar);
            }
            else if (tcrGrupoArchivo == "02")
